Certainly! Below is a JavaScript function that takes a string representing a dot-notation path (e.g., `name.age`) and returns all entries in an object where the nested key value matches the string key.

```javascript
function getEntriesByKey(pathString, obj) {
    // Split the path into individual keys
    const keys = pathString.split('.');

    // Initialize an empty array for results
    let result = [];

    // Iterate over each key in the path
    for (let i = 0; i < keys.length - 1; i++) {
        const currentKey = keys[i];

        // Check if the current key exists in the object
        if (obj[currentKey]) {
            // If it does, add its value to the result array
            result.push(obj[currentKey]);

            // Move on to the next level of nesting
            obj = obj[currentKey];
        } else {
            // If the current key doesn't exist, break out of the loop
            break;
        }
    }

    // Return the final result or null if no matching keys were found
    return result || null;
}

